import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  Param,
  UseGuards,
  Request,
  Query,
} from '@nestjs/common';
import { ActivitiesService } from './activities.service';
import { CreateActivityDto } from './dto/create-activity.dto';
import { UpdateActivityDto } from './dto/update-activity.dto';
import { JwtAuthGuard } from 'src/auth/guards/jwt-auth.guard';
import { RolesGuard } from 'src/auth/guards/roles.guard';
import { Roles } from 'src/auth/decorators/roles.decorator';
import { UserRole } from 'src/users/schemas/user.schema';

@Controller('activities')
@UseGuards(JwtAuthGuard, RolesGuard)
export class ActivitiesController {
  constructor(private readonly activitiesService: ActivitiesService) {}

  @Post()
  @Roles(UserRole.ADMIN)
  create(@Request() req: any, @Body() createActivityDto: CreateActivityDto) {
    return this.activitiesService.create(createActivityDto, req.user.gymId);
  }

  @Get()
  @Roles(UserRole.ADMIN, UserRole.COACH, UserRole.SUPER_ADMIN)
  findAll(@Request() req: any, @Query('gymId') gymId?: string) {
    if (req.user.role === UserRole.COACH) {
      // Coach sees only their assigned activities in this gym
      return this.activitiesService.findByCoach(
        req.user.userId,
        req.user.gymId,
      );
    }
    if (req.user.role === UserRole.SUPER_ADMIN) {
      return this.activitiesService.findAll(gymId);
    }
    // Admin sees all activities for their gym
    return this.activitiesService.findAll(req.user.gymId);
  }

  @Get(':id')
  @Roles(UserRole.ADMIN, UserRole.COACH)
  findOne(@Request() req: any, @Param('id') id: string) {
    return this.activitiesService.findOne(id, req.user.gymId);
  }

  @Patch(':id')
  @Roles(UserRole.ADMIN)
  update(
    @Request() req: any,
    @Param('id') id: string,
    @Body() updateActivityDto: UpdateActivityDto,
  ) {
    return this.activitiesService.update(id, updateActivityDto, req.user.gymId);
  }

  @Delete(':id')
  @Roles(UserRole.ADMIN)
  remove(@Request() req: any, @Param('id') id: string) {
    return this.activitiesService.remove(id, req.user.gymId);
  }
}

import {
  BadRequestException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { Activity, ActivityDocument } from './schemas/activity.schema';
import { CreateActivityDto } from './dto/create-activity.dto';
import { UpdateActivityDto } from './dto/update-activity.dto';
import { Gym, GymDocument } from '../gyms/schemas/gym.schema';

type ScheduleSlotLike = {
  day: string;
  startTime: string;
  endTime: string;
};

const getReferenceId = (value: unknown): string | null => {
  if (typeof value === 'string' || typeof value === 'number') {
    return String(value);
  }

  if (!value || typeof value !== 'object') return null;

  const maybeRecord = value as any;
  if (['string', 'number', 'bigint'].includes(typeof maybeRecord._id))
    return String(maybeRecord._id);
  if (['string', 'number', 'bigint'].includes(typeof maybeRecord.id))
    return String(maybeRecord.id);

  return null;
};

const parseTimeToMinutes = (time: string): number | null => {
  const [hourText, minuteText] = time.split(':');
  const hour = Number(hourText);
  const minute = Number(minuteText);

  if (!Number.isInteger(hour) || !Number.isInteger(minute)) return null;
  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;

  return hour * 60 + minute;
};

const slotsOverlap = (left: ScheduleSlotLike, right: ScheduleSlotLike) => {
  if (left.day !== right.day) return false;

  const leftStart = parseTimeToMinutes(left.startTime);
  const leftEnd = parseTimeToMinutes(left.endTime);
  const rightStart = parseTimeToMinutes(right.startTime);
  const rightEnd = parseTimeToMinutes(right.endTime);

  if (
    leftStart === null ||
    leftEnd === null ||
    rightStart === null ||
    rightEnd === null
  )
    return false;

  return leftStart < rightEnd && rightStart < leftEnd;
};

@Injectable()
export class ActivitiesService {
  constructor(
    @InjectModel(Activity.name) private activityModel: Model<ActivityDocument>,
    @InjectModel(Gym.name) private gymModel: Model<GymDocument>,
  ) {}

  private getGymHallOrThrow(gym: Gym, hallId: string) {
    const hall = gym.halls?.find((entry) => entry._id?.toString() === hallId);
    if (!hall) throw new NotFoundException('Hall not found in this gym');
    return hall;
  }

  private validateScheduleSlots(slots: ScheduleSlotLike[]) {
    if (!slots.length) {
      throw new BadRequestException('At least one schedule slot is required.');
    }

    for (const slot of slots) {
      const start = parseTimeToMinutes(slot.startTime);
      const end = parseTimeToMinutes(slot.endTime);

      if (start === null || end === null) {
        throw new BadRequestException(
          'Invalid schedule time format. Use HH:mm.',
        );
      }

      if (start >= end) {
        throw new BadRequestException(
          'Schedule start time must be before end time.',
        );
      }
    }

    const hasInternalOverlap = slots.some((slotA, i) =>
      slots.some((slotB, j) => i !== j && slotsOverlap(slotA, slotB)),
    );

    if (hasInternalOverlap) {
      throw new BadRequestException(
        'Activity schedule contains overlapping time slots internally.',
      );
    }
  }

  private ensureHallCapacity(maxCapacity: number, hallCapacity: number) {
    if (maxCapacity > hallCapacity) {
      throw new BadRequestException(
        `Max capacity cannot exceed selected hall capacity (${hallCapacity}).`,
      );
    }
  }

  private async ensureNoScheduleConflicts(params: {
    gymId: string;
    hallId: string;
    coachId: string;
    schedule: ScheduleSlotLike[];
    excludeActivityId?: string;
  }) {
    const { gymId, hallId, coachId, schedule, excludeActivityId } = params;
    if (!schedule.length) return;

    const existingActivities = await this.activityModel
      .find({
        gymId,
        _id: { $ne: excludeActivityId },
        $or: [{ hallId }, { coach: coachId }],
      })
      .select('name hallId coach schedule')
      .lean()
      .exec();

    for (const existingActivity of existingActivities) {
      const existingSlots =
        (existingActivity.schedule as ScheduleSlotLike[]) || [];

      const overlappingSlot = schedule.find((incoming) =>
        existingSlots.some((existing) => slotsOverlap(incoming, existing)),
      );

      if (overlappingSlot) {
        if (String(existingActivity.hallId) === hallId) {
          throw new BadRequestException(
            `Hall is already occupied on ${overlappingSlot.day} during ${overlappingSlot.startTime}-${overlappingSlot.endTime}.`,
          );
        }

        if (getReferenceId(existingActivity.coach) === coachId) {
          throw new BadRequestException(
            `Coach is already assigned on ${overlappingSlot.day} during ${overlappingSlot.startTime}-${overlappingSlot.endTime}.`,
          );
        }
      }
    }
  }

  async create(
    createActivityDto: CreateActivityDto,
    gymId: string,
  ): Promise<Activity> {
    const gym = await this.gymModel.findById(gymId).exec();
    if (!gym) throw new NotFoundException(`Gym with ID "${gymId}" not found`);

    const hall = this.getGymHallOrThrow(gym, createActivityDto.hallId);
    this.ensureHallCapacity(createActivityDto.maxCapacity, hall.capacity);

    const incomingSchedule = createActivityDto.schedule ?? [];
    this.validateScheduleSlots(incomingSchedule);

    await this.ensureNoScheduleConflicts({
      gymId,
      hallId: createActivityDto.hallId,
      coachId: createActivityDto.coach,
      schedule: incomingSchedule,
    });

    const createdActivity = new this.activityModel({
      ...createActivityDto,
      gymId,
    });

    return createdActivity.save();
  }

  async findAll(gymId?: string): Promise<Activity[]> {
    const filter = gymId ? { gymId } : {};
    return this.activityModel
      .find(filter)
      .populate('coach', 'firstName lastName email')
      .populate('gymId', 'name')
      .exec();
  }

  async findByCoach(coachId: string, gymId: string): Promise<Activity[]> {
    return this.activityModel
      .find({ coach: coachId, gymId })
      .populate('coach', 'firstName lastName email')
      .exec();
  }

  async findOne(id: string, gymId: string): Promise<Activity> {
    const activity = await this.activityModel
      .findOne({ _id: id, gymId })
      .populate('coach', 'firstName lastName email')
      .exec();

    if (!activity) {
      throw new NotFoundException(
        `Activity with ID "${id}" not found in your gym`,
      );
    }

    return activity;
  }

  async update(
    id: string,
    updateActivityDto: UpdateActivityDto,
    gymId: string,
  ): Promise<Activity> {
    const existingActivity = await this.activityModel
      .findOne({ _id: id, gymId })
      .exec();
    if (!existingActivity) {
      throw new NotFoundException(
        `Activity with ID "${id}" not found in your gym`,
      );
    }

    const gym = await this.gymModel.findById(gymId).exec();
    if (!gym) throw new NotFoundException(`Gym with ID "${gymId}" not found`);

    const nextHallId =
      updateActivityDto.hallId || existingActivity.hallId?.toString() || '';
    const nextCoachId =
      updateActivityDto.coach || getReferenceId(existingActivity.coach) || '';

    if (!nextHallId) throw new NotFoundException('Hall not found in this gym');
    if (!nextCoachId)
      throw new BadRequestException('Coach is required for this activity.');

    const nextMaxCapacity =
      updateActivityDto.maxCapacity ?? existingActivity.maxCapacity;
    const nextSchedule =
      (updateActivityDto.schedule as ScheduleSlotLike[]) ??
      (existingActivity.schedule as ScheduleSlotLike[]) ??
      [];

    const hall = this.getGymHallOrThrow(gym, nextHallId);

    if (
      updateActivityDto.maxCapacity !== undefined ||
      updateActivityDto.hallId !== undefined
    ) {
      this.ensureHallCapacity(nextMaxCapacity, hall.capacity);
    }

    this.validateScheduleSlots(nextSchedule);

    if (
      updateActivityDto.schedule ||
      updateActivityDto.hallId ||
      updateActivityDto.coach
    ) {
      await this.ensureNoScheduleConflicts({
        gymId,
        hallId: nextHallId,
        coachId: nextCoachId,
        schedule: nextSchedule,
        excludeActivityId: id,
      });
    }

    const updatedActivity = await this.activityModel
      .findOneAndUpdate({ _id: id, gymId }, updateActivityDto, { new: true })
      .populate('coach', 'firstName lastName email')
      .exec();

    if (!updatedActivity)
      throw new NotFoundException(
        `Activity with ID "${id}" not found in your gym`,
      );

    return updatedActivity;
  }

  async remove(id: string, gymId: string): Promise<Activity> {
    const deletedActivity = await this.activityModel
      .findOneAndDelete({ _id: id, gymId })
      .exec();
    if (!deletedActivity) {
      throw new NotFoundException(
        `Activity with ID "${id}" not found in your gym`,
      );
    }
    return deletedActivity;
  }
}

import {
  Controller,
  Post,
  Get,
  Body,
  UseGuards,
  Request,
} from '@nestjs/common';
import { AuthService } from './auth.service';
import { LoginDto } from './dto/login.dto';
import { CreateUserDto } from '../users/dto/create-user.dto';
import { RolesGuard } from './guards/roles.guard';
import { JwtAuthGuard } from './guards/jwt-auth.guard';
import { Roles } from './decorators/roles.decorator';
import { UserRole } from 'src/users/schemas/user.schema';

@Controller('auth')
export class AuthController {
  constructor(private authService: AuthService) {}

  @Post('login')
  async login(@Body() loginDto: LoginDto) {
    return this.authService.login(loginDto);
  }

  @Post('register')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles(UserRole.SUPER_ADMIN, UserRole.ADMIN)
  async register(@Body() createUserDto: CreateUserDto) {
    return this.authService.register(createUserDto);
  }

  @Get('me')
  @UseGuards(JwtAuthGuard)
  async getProfile(@Request() req: any) {
    return this.authService.getProfile(req.user.userId, req.user.role);
  }
}

import { Module } from '@nestjs/common';
import { AuthService } from './auth.service';
import { UsersModule } from '../users/users.module';
import { MembersModule } from '../members/members.module';
import { PassportModule } from '@nestjs/passport';
import { JwtModule } from '@nestjs/jwt';
import { ConfigModule, ConfigService } from '@nestjs/config';
import { JwtStrategy } from './strategies/jwt.strategy';
import { AuthController } from './auth.controller';

@Module({
  imports: [
    UsersModule,
    MembersModule,
    PassportModule,
    JwtModule.registerAsync({
      imports: [ConfigModule],
      useFactory: async (configService: ConfigService) => ({
        secret: configService.get<string>('JWT_SECRET') || 'secret',
        signOptions: { expiresIn: '1d' },
      }),
      inject: [ConfigService],
    }),
  ],
  providers: [AuthService, JwtStrategy],
  controllers: [AuthController],
  exports: [AuthService],
})
export class AuthModule {}

import { AuthService } from './auth.service';
import { UserRole } from '../users/schemas/user.schema';

describe('AuthService', () => {
  let service: AuthService;
  let usersService: { findOne: jest.Mock; findByEmail: jest.Mock };
  let membersService: { findById: jest.Mock; findByEmail: jest.Mock };

  beforeEach(() => {
    usersService = {
      findOne: jest.fn(),
      findByEmail: jest.fn(),
    };
    membersService = {
      findById: jest.fn(),
      findByEmail: jest.fn(),
    };

    service = new AuthService(
      usersService as any,
      membersService as any,
      {} as any,
    );
  });

  it('returns member profile with role', async () => {
    const memberDoc = {
      toObject: () => ({ _id: 'member-id', email: 'member@test.com' }),
    };

    membersService.findById.mockResolvedValue(memberDoc);

    const result = await service.getProfile('member-id', UserRole.MEMBER);

    expect(result).toEqual({
      _id: 'member-id',
      email: 'member@test.com',
      role: UserRole.MEMBER,
    });
  });

  it('returns user profile for non-member role', async () => {
    usersService.findOne.mockResolvedValue({ _id: 'user-id' });

    const result = await service.getProfile('user-id', UserRole.ADMIN);

    expect(usersService.findOne).toHaveBeenCalledWith('user-id');
    expect(result).toEqual({ _id: 'user-id' });
  });
});

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { UsersService } from '../users/users.service';
import { MembersService } from '../members/members.service';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import { LoginDto } from './dto/login.dto';
import { CreateUserDto } from '../users/dto/create-user.dto';
import { UserRole } from '../users/schemas/user.schema';

@Injectable()
export class AuthService {
  constructor(
    private usersService: UsersService,
    private membersService: MembersService,
    private jwtService: JwtService,
  ) {}

  async validateUser(email: string, pass: string): Promise<any> {
    const user = await this.usersService.findByEmail(email);

    if (user && (await bcrypt.compare(pass, user.passwordHash))) {
      const { passwordHash: _ph, ...result } = user.toObject();
      return { ...result, isMember: false };
    }

    const member = await this.membersService.findByEmail(email);

    if (member && (await bcrypt.compare(pass, member.passwordHash))) {
      const { passwordHash: _ph, ...result } = member.toObject();
      return { ...result, isMember: true };
    }

    return null;
  }

  async login(loginDto: LoginDto) {
    const user = await this.validateUser(loginDto.email, loginDto.password);

    if (!user) throw new UnauthorizedException('Invalid credentials');

    const role = user.isMember ? UserRole.MEMBER : user.role;

    const payload = {
      email: user.email,
      sub: user._id,
      role,
      gymId: user.gymId || null,
    };

    const { isMember: _, ...userData } = user;

    return {
      access_token: this.jwtService.sign(payload),
      user: { ...userData, role },
    };
  }

  async register(registrationData: CreateUserDto) {
    return this.usersService.create(registrationData);
  }

  async getProfile(userId: string, role: string) {
    if (role === (UserRole.MEMBER as string)) {
      const member = await this.membersService.findById(userId);
      return { ...member.toObject(), role: UserRole.MEMBER };
    }

    return this.usersService.findOne(userId);
  }
}

import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY } from '../decorators/roles.decorator';
import { UserRole } from '../../users/schemas/user.schema';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<UserRole[]>(
      ROLES_KEY,
      [context.getHandler(), context.getClass()],
    );
    if (!requiredRoles) {
      return true;
    }
    const { user } = context.switchToHttp().getRequest();
    return requiredRoles.some((role) => user.role === role);
  }
}

import { ExtractJwt, Strategy } from 'passport-jwt';
import { PassportStrategy } from '@nestjs/passport';
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(configService: ConfigService) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: configService.get<string>('JWT_SECRET') || 'secret',
    });
  }

  validate(payload: any) {
    return {
      userId: payload.sub,
      email: payload.email,
      role: payload.role,
      gymId: payload.gymId || null,
    };
  }
}

import {
  IsArray,
  IsBoolean,
  IsMongoId,
  IsNotEmpty,
  IsNumber,
  IsOptional,
  IsString,
  Min,
  ValidateNested,
} from 'class-validator';
import { plainToInstance, Transform, Type } from 'class-transformer';

export class HallDto {
  @IsOptional()
  @IsMongoId()
  _id?: string;

  @IsString()
  @IsNotEmpty()
  name: string;

  @IsString()
  @IsNotEmpty()
  type: string;

  @IsNumber()
  @Min(1)
  capacity: number;
}

export class CreateGymDto {
  @IsString()
  @IsNotEmpty()
  name: string;

  @IsString()
  @IsNotEmpty()
  address: string;

  @IsString()
  @IsNotEmpty()
  phone: string;

  @IsString()
  @IsOptional()
  logo?: string;

  @IsBoolean()
  @IsOptional()
  @Transform(({ value }) => value === 'true' || value === true)
  isActive?: boolean;

  @IsArray()
  @IsOptional()
  @ValidateNested({ each: true })
  @Type(() => HallDto)
  @Transform(
    ({ value }) => {
      if (value === undefined || value === null) {
        return value;
      }

      let parsed = value;
      if (typeof value === 'string') {
        if (!value.trim()) {
          return [];
        }
        try {
          parsed = JSON.parse(value);
        } catch {
          return value;
        }
      }

      if (!Array.isArray(parsed)) {
        return parsed;
      }

      return plainToInstance(HallDto, parsed);
    },
    { toClassOnly: true },
  )
  halls?: HallDto[];
}

import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { ValidationPipe } from '@nestjs/common';
import { join } from 'path';
import { NestExpressApplication } from '@nestjs/platform-express';

async function bootstrap() {
  const app = await NestFactory.create<NestExpressApplication>(AppModule);

  // Serve uploaded files statically
  app.useStaticAssets(join(__dirname, '..', 'uploads'), {
    prefix: '/uploads/',
  });

  app.enableCors({
    origin: true,
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  });

  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
    }),
  );

  await app.listen(process.env.PORT ?? 3000);
}
bootstrap();

import { BadRequestException } from '@nestjs/common';
import { MembersController } from './members.controller';
import { UserRole } from '../users/schemas/user.schema';

describe('MembersController', () => {
  let controller: MembersController;
  let membersService: {
    create: jest.Mock;
    findAll: jest.Mock;
    findByCoach: jest.Mock;
  };

  beforeEach(() => {
    membersService = {
      create: jest.fn(),
      findAll: jest.fn(),
      findByCoach: jest.fn(),
    };

    controller = new MembersController(membersService as any);
  });

  it('throws when super admin creates without gymId', () => {
    const req = { user: { role: UserRole.SUPER_ADMIN } } as any;
    const dto = {
      firstName: 'A',
      lastName: 'B',
      email: 'member@test.com',
      password: 'secret',
    } as any;

    expect(() => controller.create(req, dto)).toThrow(BadRequestException);
  });

  it('creates member with gymId from dto for super admin', () => {
    const req = { user: { role: UserRole.SUPER_ADMIN } } as any;
    const dto = {
      firstName: 'A',
      lastName: 'B',
      email: 'member@test.com',
      password: 'secret',
      gymId: 'gym-id',
    } as any;

    controller.create(req, dto);

    expect(membersService.create).toHaveBeenCalledWith(dto, 'gym-id');
  });

  it('findAll for coach uses findByCoach', () => {
    const req = {
      user: { role: UserRole.COACH, userId: 'coach-id', gymId: 'gym-id' },
    } as any;

    controller.findAll(req);

    expect(membersService.findByCoach).toHaveBeenCalledWith(
      'coach-id',
      'gym-id',
    );
  });
});

import {
  Controller,
  Get,
  Post,
  Body,
  Patch,
  Param,
  Delete,
  BadRequestException,
  UseGuards,
  Request,
  Query,
} from '@nestjs/common';
import { MembersService } from './members.service';
import { CreateMemberDto } from './dto/create-member.dto';
import { UpdateMemberDto } from './dto/update-member.dto';
import { JwtAuthGuard } from 'src/auth/guards/jwt-auth.guard';
import { RolesGuard } from 'src/auth/guards/roles.guard';
import { Roles } from 'src/auth/decorators/roles.decorator';
import { UserRole } from 'src/users/schemas/user.schema';

@Controller('members')
@UseGuards(JwtAuthGuard, RolesGuard)
export class MembersController {
  constructor(private readonly membersService: MembersService) {}

  @Post()
  @Roles(UserRole.ADMIN, UserRole.COACH, UserRole.SUPER_ADMIN)
  create(@Request() req: any, @Body() createMemberDto: CreateMemberDto) {
    if (req.user.role === UserRole.SUPER_ADMIN) {
      if (!createMemberDto.gymId) {
        throw new BadRequestException('gymId is required to create a member');
      }
      return this.membersService.create(createMemberDto, createMemberDto.gymId);
    }
    return this.membersService.create(createMemberDto, req.user.gymId);
  }

  @Get()
  @Roles(UserRole.ADMIN, UserRole.COACH, UserRole.SUPER_ADMIN)
  findAll(@Request() req: any, @Query('gymId') gymId?: string) {
    if (req.user.role === UserRole.SUPER_ADMIN) {
      return this.membersService.findAll(gymId);
    }

    // Admin and coach both see all members in their gym.
    return this.membersService.findAll(req.user.gymId);
  }

  @Get(':id')
  @Roles(UserRole.ADMIN, UserRole.COACH)
  findOne(@Request() req: any, @Param('id') id: string) {
    return this.membersService.findOne(id, req.user.gymId);
  }

  @Patch(':id')
  @Roles(UserRole.ADMIN, UserRole.COACH)
  update(
    @Request() req: any,
    @Param('id') id: string,
    @Body() updateMemberDto: UpdateMemberDto,
  ) {
    return this.membersService.update(id, updateMemberDto, req.user.gymId);
  }

  @Delete(':id')
  @Roles(UserRole.ADMIN)
